mapper.select:
SELECT 
FROM ecom_owh_diff d
LEFT JOIN wms_warehouse w ON w.id = d.warehouse_id
LEFT JOIN wms_material mt ON mt.id = d.material_id

    AND d.source_type = #{sourceType}
    AND d.status = #{status}
    AND d.warehouse_id = #{warehouseId}

        AND (d.source_no LIKE CONCAT('%', #{keyword}, '%') OR d.ref_no LIKE CONCAT('%', #{keyword}, '%')
             OR d.sku LIKE CONCAT('%', #{keyword}, '%') OR mt.name LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY d.id DESC
